<style>
:root{color-scheme:light;font:12px/1.5 system-ui,sans-serif;background:#F4F7FB;color:#1F2937;--border:#DCE4EE;--muted:#64748B;--primary:#0891B2;--danger:#DC2626;--good:#16A34A}
*{box-sizing:border-box}body{margin:0;display:flex;min-height:100vh}nav{width:146px;flex:none;background:#EEF3F8;border-right:1px solid var(--border);padding:14px 7px}nav h1{font-size:14px;color:#155E75;margin:2px 8px 18px}nav button{display:block;width:100%;text-align:left;margin:2px 0;border:0;background:transparent;color:var(--muted);padding:9px 10px}nav button.active,nav button:hover{background:#DBEAF2;color:#155E75}main{min-width:0;flex:1;padding:12px 16px}header{min-height:34px;display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:8px}h2{font-size:17px;margin:0}h3{font-size:14px}.toolbar,.stats,.formrow{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:8px 0}.stats span{border:1px solid var(--border);background:#FFF;padding:6px 10px;border-radius:4px}.box{border:1px solid var(--border);background:#FFF;padding:12px;margin:10px 0;border-radius:5px}.scroll{max-height:75vh;overflow:auto;border:1px solid var(--border);background:#FFF;border-radius:4px}table{border-collapse:collapse;width:100%;font-size:12px;white-space:nowrap}th,td{padding:7px 9px;border-bottom:1px solid var(--border);text-align:left;min-height:36px}th{background:#EEF3F8;color:#475569;position:sticky;top:0;z-index:1}tr:hover td{background:#F4F9FC}button,input,select,textarea{font:inherit;color:#1F2937;background:#FFF;border:1px solid #CBD5E1;padding:6px 9px;border-radius:4px}button{cursor:pointer}button:hover{border-color:var(--primary)}button:disabled{opacity:.6;cursor:wait}button.primary{background:var(--primary);border-color:var(--primary);color:#FFF}button.danger{background:#FFF1F2;color:var(--danger);border-color:#FECACA}button.danger.primary{background:var(--danger);border-color:var(--danger);color:#FFF}.danger{color:var(--danger)}.good{color:var(--good)}.muted{color:var(--muted)}.pill{display:inline-block;margin-right:3px;border:1px solid var(--border);padding:1px 5px;border-radius:3px}label{display:inline-flex;align-items:center;gap:6px}input{min-width:170px;max-width:100%}input[type=number]{min-width:65px;width:100px}input[type=checkbox]{min-width:0}.token-input{width:340px;max-width:70vw;font-family:monospace}.token-full{display:inline-block;min-width:32ch;font:12px/1.5 ui-monospace,Consolas,monospace;color:#0E7490;white-space:nowrap;user-select:text;cursor:copy}.wrap{white-space:normal;max-width:260px;overflow-wrap:anywhere}.actions{display:inline-flex;gap:4px}#message{min-height:20px;color:var(--good);overflow-wrap:anywhere}.empty{padding:16px;color:var(--muted)}dialog{background:#FFF;color:#1F2937;border:1px solid var(--border);border-radius:7px;padding:18px;max-width:95vw;max-height:90vh;overflow:auto;width:min(560px,95vw);box-shadow:0 16px 48px #33415526}dialog.wide,#detail{width:min(1060px,95vw)}dialog::backdrop{background:#47556966}.dialog-title{font-size:16px;margin:0 0 8px}.dialog-description{color:var(--muted);white-space:pre-line;margin:0 0 14px}.dialog-footer{display:flex;justify-content:flex-end;gap:8px;margin-top:16px}.dialog-error{min-height:18px;color:var(--danger);white-space:pre-line}.mapping-target{width:380px;min-width:190px;max-width:100%}.source-host{font-family:monospace;min-width:260px}.dialog-body .scroll{max-height:55vh}input:focus-visible,select:focus-visible,button:focus-visible,textarea:focus-visible{outline:2px solid #67C9DC;outline-offset:2px}.copy-fallback{width:100%;min-height:72px;font-family:monospace}@media(max-width:700px){nav{width:98px;padding:10px 4px}nav h1{font-size:12px;margin:2px 4px 12px}main{padding:8px}.scroll{max-height:70vh}label{flex-wrap:wrap}.source-host{min-width:190px}.token-input{width:300px}dialog{padding:12px}.mapping-target{width:240px}}
.mapping-target.mapping-empty{border-color:var(--danger);background:#FFF1F2}.pill.mapping-done{color:#15803D;background:#F0FDF4;border-color:#86EFAC}.pill.mapping-partial{color:#B45309;background:#FFFBEB;border-color:#FCD34D}.pill.mapping-missing{color:var(--danger);background:#FFF1F2;border-color:#FECACA}.tracking-warning{border-color:#FCD34D;background:#FFFBEB}.split-preview{white-space:pre-line;max-height:220px;overflow:auto}.group-path{display:inline-block;font-family:monospace}
</style></head><body>
<nav><h1>订阅清洗网关</h1><div id="menu"></div><button id="logout">退出登录</button></nav>
<main><header><h2 id="title">概览</h2><span id="identity" class="muted"></span></header><div id="message" role="status" aria-live="polite"></div><div id="content"></div></main>
<dialog id="detail" aria-label="Token 详情"><div class="toolbar"><strong>Token 详情</strong><button id="close-detail">关闭</button></div><div id="detail-content"></div></dialog>
<dialog id="modal" aria-labelledby="modal-title" aria-describedby="modal-description">
<form id="modal-form"><h2 id="modal-title" class="dialog-title"></h2><p id="modal-description" class="dialog-description"></p><div id="modal-body" class="dialog-body"></div><div id="modal-error" class="dialog-error" role="status"></div><div class="dialog-footer"><button id="modal-cancel" type="button">取消</button><button id="modal-save" type="submit" class="primary">确认</button></div></form>
</dialog>
<script>
const base=<?= json_encode($basePath, JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;
const csrf=document.querySelector('meta[name="csrf-token"]').content;
const content=document.getElementById('content'),msg=document.getElementById('message');
const pages=['概览','分析','日志','Token','入口追踪','IP规则','UA规则','设置'];
let tokenGroupFilter='',currentPage='概览';
const stateLabels={NORMAL:'正常',WHITELIST:'白名单',BLOCKED:'永久封禁',TEMP_BLOCKED:'临时封禁',BLACKLIST:'黑名单',ACTIVE:'已启用',DRAFT:'待配置',ARCHIVED:'已归档',off:'关闭',preflight:'预检模式',enforced:'正式模式'};
const decisionLabels={PASS:'正常放行',TOKEN_BLOCKED:'Token黑名单',TOKEN_TEMP_BLOCKED:'Token临时封禁',IP_BLACKLIST:'IP黑名单',TOKEN_WHITELIST:'Token白名单',IP_WHITELIST:'IP白名单',UA_WHITELIST:'UA白名单',UA_BLACKLIST:'UA黑名单',RATE_LIMIT:'请求限速'};
const httpLabels={200:'成功',400:'请求错误',401:'未授权',403:'已拦截',404:'未找到',429:'已限速',444:'网关已断开',500:'服务错误',502:'上游/转换异常',503:'服务暂不可用',504:'上游超时'};
function node(tag,value='',cls=''){const x=document.createElement(tag);x.textContent=value;if(cls)x.className=cls;return x}
function add(parent,...children){parent.append(...children);return parent}
function field(label,value='',type='text'){const l=node('label',label),i=node('input');i.type=type;i.value=value;l.append(i);return[l,i]}
function errorText(e){return /[\u3400-\u9fff]/.test(e.message||'')?e.message:'操作失败，请检查网络或重新登录后重试。'}
function btn(text,run,cls=''){const b=node('button',text,cls);b.type='button';b.onclick=()=>Promise.resolve().then(run).catch(e=>notice(errorText(e),true));return b}
function options(items,placeholder){const s=node('select');if(placeholder){const o=node('option',placeholder);o.value='';s.append(o)}items.forEach(([value,label])=>{const o=node('option',label);o.value=value;s.append(o)});return s}
function table(headers,rows){const box=node('div','','scroll'),t=node('table'),head=node('tr');headers.forEach(h=>head.append(node('th',h)));t.append(add(node('thead'),head));const body=node('tbody');rows.forEach(items=>{const tr=node('tr');items.forEach(item=>{const td=node('td');if(item instanceof Node)td.append(item);else td.textContent=item??'—';tr.append(td)});body.append(tr)});if(!rows.length){const cell=node('td','暂无记录','empty');cell.colSpan=headers.length;body.append(add(node('tr'),cell))}t.append(body);box.append(t);return box}
function notice(text,error=false){msg.textContent=text;msg.style.color=error?'var(--danger)':'var(--good)'}
function statusText(v){const n=Number(v),label=httpLabels[n]||(n>=500?'服务异常':n>=400?'请求被拒绝':n>=300?'重定向':n>=200?'已响应':'其他状态');return n+' '+label}
function decisionView(code){const el=node('span',decisionLabels[code]||'其他处理结果');el.title=code||'无处理记录';return el}
function stateView(code){const el=node('span',stateLabels[code]||'其他状态');el.title=code;return el}
async function api(path,method='GET',data){const r=await fetch(base+'/api/'+path,{method,credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:data===undefined?undefined:JSON.stringify(data)});let value;try{value=await r.json()}catch{throw Error('服务器响应异常，请稍后重试')}if(!r.ok||!value.ok)throw Error(value.error||'请求失败');return value}
async function show(page){currentPage=page;document.getElementById('title').textContent=page;content.replaceChildren();msg.textContent='';document.querySelectorAll('#menu button').forEach(b=>b.classList.toggle('active',b.textContent===page));try{await render[page]()}catch(e){notice(errorText(e),true)}}
function fmtTime(v){return v?new Date(Number(v)*1000).toLocaleString():'—'}
function publishNotice(x){notice(x.publish?.applied===true?'已保存，网关规则已应用':'已保存，网关规则应用待确认')}

// One reusable component for confirmations, inputs and structured large forms.
function openDialog({title,description='',build,submit=()=>true,label='确认',danger=false,wide=false}){
    const modal=document.getElementById('modal'),form=document.getElementById('modal-form'),body=document.getElementById('modal-body'),error=document.getElementById('modal-error'),save=document.getElementById('modal-save'),cancel=document.getElementById('modal-cancel');
    if(modal.open)return Promise.reject(Error('请先完成或关闭当前弹窗'));
    document.getElementById('modal-title').textContent=title;document.getElementById('modal-description').textContent=description;body.replaceChildren();error.textContent='';save.textContent=label;save.className=danger?'primary danger':'primary';modal.classList.toggle('wide',wide);
    if(build)build(body);
    return new Promise(resolve=>{
        let pending=false;
        function finish(value){form.onsubmit=null;cancel.onclick=null;modal.removeEventListener('cancel',onCancel);modal.close();resolve(value)}
        function onCancel(event){event.preventDefault();if(!pending)finish(null)}
        cancel.onclick=()=>{if(!pending)finish(null)};modal.addEventListener('cancel',onCancel);
        form.onsubmit=async event=>{event.preventDefault();if(pending||!form.reportValidity())return;pending=true;save.disabled=cancel.disabled=true;error.textContent='';try{const result=await submit();finish(result)}catch(e){error.textContent=errorText(e)}finally{pending=false;save.disabled=cancel.disabled=false}};
        save.disabled=cancel.disabled=false;modal.showModal();
    });
}
const ask=options=>openDialog(options);
async function copyToken(token){
    try{await navigator.clipboard.writeText(token)}catch{
        const area=node('textarea');area.value=token;area.style.position='fixed';area.style.left='-9999px';area.setAttribute('aria-hidden','true');const parent=document.querySelector('dialog[open]')||document.body,previous=document.activeElement;parent.append(area);area.select();let copied=false;try{copied=document.execCommand('copy')}catch{}finally{area.remove();previous?.focus()}
        if(!copied){await openDialog({title:'手动复制 Token',description:'自动复制不可用，请选中完整 Token，按 Ctrl+C（手机可长按复制）。',label:'关闭',build:body=>{const input=node('textarea','','copy-fallback');input.value=token;input.readOnly=true;body.append(input);setTimeout(()=>{input.focus();input.select()},0)}});return}
    }
    notice('✓ Token 已复制');
}
function tokenView(token){if(!token)return node('span','—','muted');const text=node('span',token,'token-full');text.title='双击复制完整 Token';text.ondblclick=()=>copyToken(token).catch(e=>notice(errorText(e),true));return text}
async function stateChange(id,state){
    let hours;
    const temporary=state==='TEMP_BLOCKED';
    const result=await openDialog({title:temporary?'临时封禁 Token':'修改 Token 状态',description:temporary?'请选择封禁时间，或填写自定义小时数。':'确认将 Token 设置为“'+stateLabels[state]+'”？',label:temporary?'确认封禁':'确认修改',danger:state==='BLOCKED'||temporary,
        build:temporary?body=>{const quick=node('div','','toolbar'),pair=field('自定义小时数','1','number');hours=pair[1];hours.min='0.001';hours.max='8760';hours.step='any';hours.required=true;[[1,'1小时'],[24,'24小时'],[168,'7天']].forEach(([value,label])=>quick.append(btn(label,()=>{hours.value=value})));body.append(quick,pair[0])}:undefined,
        submit:()=>{let expires_at=null;if(temporary){const n=Number(hours.value);if(!Number.isFinite(n)||n<=0||n>8760)throw Error('小时数应大于0且不超过8760');expires_at=Math.floor(Date.now()/1000+n*3600)}return api('tokens/'+id+'/state','PATCH',{state,expires_at})}});
    if(result){await show(currentPage);publishNotice(result)}
}
async function overview(){const o=(await api('overview')).overview,p=o.publish,bar=node('div','','stats');[['入口',o.gateway_domain],['上游',o.upstream_url||'未配置（失败关闭）'],['规则版本',p.config_version+' / '+p.active_version],['今日请求',o.today.requests],['今日Token',o.today.tokens],['今日IP',o.today.ips],['已拦截',o.today.blocked],['已限速',o.today.rate_limited],['数据库',o.database_bytes+' 字节'],['证书到期',fmtTime(o.certificate_expires_at)]].forEach(([k,v])=>bar.append(node('span',k+'：'+(v??'—'))));content.append(bar);if(!o.upstream_url)content.append(node('div','上游尚未配置，网关保持失败关闭，不会放行订阅。','box danger'));content.append(btn('重新应用当前规则',async()=>publishNotice(await api('gateway/apply','POST'))))}
async function analysis(groupId='',embedded=false){
    const query=new URLSearchParams({limit:'50'});if(groupId)query.set('group_id',groupId);const rows=(await api('analysis/tokens?'+query)).rows,bar=node('div','','toolbar');add(bar,node('span','最近50个 Token · 双击完整 Token 可复制'),btn('刷新',()=>show(embedded?'Token':'分析')));content.append(bar);
    content.append(table(['健康度','Token','入口组','1m','5m','1h','24h','IP','UA','错误','最后IP','最后UA','最后访问','状态','风险','操作'],rows.map(r=>{const actions=node('span','','actions');add(actions,btn('详情',()=>detail(r.id)),btn('白名单',()=>stateChange(r.id,'WHITELIST')),btn('永久封禁',()=>stateChange(r.id,'BLOCKED')),btn('临时封禁',()=>stateChange(r.id,'TEMP_BLOCKED')),btn('解封',()=>stateChange(r.id,'NORMAL')));const risk=node('span');(r.labels.length?r.labels:['正常']).forEach(label=>risk.append(node('span',label,'pill')));return[r.health,tokenView(r.token),r.tracking_group_path||'—',r.requests_1m,r.requests_5m,r.requests_1h,r.requests_24h,r.ips_24h,r.uas_24h,r.errors_24h,r.last_ip,node('span',r.last_ua||'—','wrap'),fmtTime(r.last_seen),stateView(r.state),risk,actions]})))
}
async function detail(id,window='24h'){
    const d=(await api('tokens/'+id+'/detail?window='+window)).detail,area=document.getElementById('detail-content');area.replaceChildren();const bar=node('div','','toolbar');add(bar,tokenView(d.token.token),node('span','状态：'+stateLabels[d.token.state]+'　入口组：'+(d.token.tracking_group_path||'—')+'　总请求：'+d.token.request_count+'　首次：'+fmtTime(d.token.first_seen)+'　最后：'+fmtTime(d.token.last_seen)));area.append(bar);const windows=node('div','','toolbar');[['1h','1小时'],['24h','24小时'],['7d','7天'],['30d','30天']].forEach(([w,label])=>windows.append(btn(label,()=>detail(id,w))));area.append(windows);area.append(table(['时间','IP','UA','状态','处理结果','路径'],d.logs.map(l=>[fmtTime(l.created_at),l.client_ip,node('span',l.user_agent,'wrap'),statusText(l.status_code),decisionView(l.decision),l.request_path])));area.append(node('h3','IP 汇总'),table(['IP','次数'],d.groups.ip.map(x=>[x.value,x.count])),node('h3','UA 汇总'),table(['UA','次数'],d.groups.ua.map(x=>[x.value,x.count])));const dialog=document.getElementById('detail');if(!dialog.open)dialog.showModal()
}
async function tokenPage(){const tracking=(await api('tracking')).tracking,bar=node('div','','toolbar'),[label,input]=field('完整 Token'),select=options(['NORMAL','WHITELIST','BLOCKED'].map(x=>[x,stateLabels[x]])),group=options(tracking.groups.filter(x=>x.status==='ACTIVE'&&!x.has_active_children).map(x=>[x.id,x.path]),'全部入口组');input.className='token-input';input.placeholder='粘贴完整32位 Token';group.value=tokenGroupFilter;group.onchange=()=>{tokenGroupFilter=group.value;show('Token')};add(bar,label,select,btn('手动添加',async()=>{const result=await api('tokens','POST',{token:input.value,state:select.value});await show('Token');publishNotice(result)}),node('span','入口组筛选：'),group);content.append(bar);await analysis(tokenGroupFilter,true)}
async function logs(page=1){
    content.replaceChildren();const bar=node('div','','toolbar'),range=options([['1h','1小时'],['24h','24小时'],['7d','7天'],['30d','30天']]);range.value='24h';const [lip,ip]=field('IP'),[lua,ua]=field('UA'),[lt,token]=field('Token');token.className='token-input';token.placeholder='粘贴完整 Token 精确查询';const status=options(Object.keys(httpLabels).map(code=>[code,statusText(code)]),'全部状态'),decision=options(Object.entries(decisionLabels),'全部处理结果');add(bar,range,lt,lip,lua,status,decision);content.append(bar);const pager=node('div','','toolbar');content.append(pager);
    async function load(p){const query=new URLSearchParams({window:range.value,page:p});if(ip.value)query.set('ip',ip.value);if(ua.value)query.set('ua',ua.value);if(status.value)query.set('status',status.value);if(decision.value)query.set('decision',decision.value);if(token.value)query.set('token',token.value);const result=(await api('logs?'+query)).result,old=content.querySelector('.scroll');if(old)old.remove();content.append(table(['时间','Token','入口组','IP','UA','状态','处理结果','路径'],result.rows.map(r=>[fmtTime(r.created_at),tokenView(r.token),r.tracking_group_path||'—',r.client_ip,node('span',r.user_agent,'wrap'),statusText(r.status_code),decisionView(r.decision),r.request_path])));pager.replaceChildren(node('span','第 '+result.page+' 页'),btn('上一页',()=>load(Math.max(1,p-1))),btn('下一页',()=>load(p+1)))}bar.append(btn('查询',()=>load(1)));await load(page)
}
async function rules(kind){const path=kind==='IP规则'?'ip-rules':'ua-rules',name=kind==='IP规则'?'network':'pattern',rows=(await api(path)).rules,bar=node('div','','toolbar'),[label,input]=field(kind==='IP规则'?'IPv4/CIDR':'UA 包含'),[remark,note]=field('备注'),action=options(['WHITELIST','BLACKLIST'].map(x=>[x,stateLabels[x]]));add(bar,label,action,remark,btn('添加',async()=>{const x=await api(path,'POST',{[name]:input.value,action:action.value,note:note.value});await show(kind);publishNotice(x)}));content.append(bar);content.append(table([kind==='IP规则'?'IPv4/CIDR':'匹配内容','状态','备注','创建时间','操作'],rows.map(r=>[r[name],stateView(r.action),r.note,fmtTime(r.created_at),btn('删除',async()=>{if(!await ask({title:'删除'+kind,description:'确认删除这条规则？删除后将不再按它处理请求。',danger:true,label:'确认删除'}))return;const x=await api(path+'/'+r.id,'DELETE');await show(kind);publishNotice(x)},'danger')]))) }
async function editTrackingMappings(group,catalog=[]){
    if(!group.mappings.length){await openDialog({title:'尚未识别原入口',description:'请先切换到预检模式，让客户端通过网关拉取一次真实订阅。系统将自动识别节点连接地址，并同步到所有当前入口组。',label:'知道了'});return}
    const sources=new Map(catalog.map(s=>[s.source_host,s])),inputs=[];const result=await openDialog({title:'编辑入口映射',description:'入口组：'+group.path+'。可提前配置备用/历史入口。空目标对应节点会过滤，其它已映射节点正常下发。正式模式及子组激活至少需要1个当前可用目标。原入口增删改请使用原入口管理。',wide:true,label:'保存',build:body=>body.append(table(['原入口（只读）','状态','目标入口'],group.mappings.filter(row=>sources.get(row.source_host)?.state!=='DELETED').map(row=>{const input=node('input');input.value=row.target_host||'';input.placeholder='填写目标域名或IP（可留空）';input.className='mapping-target';const mark=()=>{const empty=!input.value.trim();input.classList.toggle('mapping-empty',empty);input.setAttribute('aria-invalid',String(empty))};input.oninput=mark;mark();inputs.push({source:row.source_host,input});return[node('code',row.source_host,'source-host'),trackingSourceState(sources.get(row.source_host)),input]}))),submit:()=>api('tracking/groups/'+group.id+'/mappings','PUT',{mappings:group.mappings.map(row=>({source_host:row.source_host,target_host:inputs.find(x=>x.source===row.source_host)?.input.value??row.target_host}))})});if(result){await show('入口追踪');notice('入口映射已保存，未映射节点将过滤')}
}
function trackingMappingState(group){
    if(group.status==='ACTIVE'&&group.has_active_children)return{text:'已拆分',className:'pill muted',complete:true,usable:true};
    const total=Number(group.mapping_count),filled=Number(group.mapping_filled_count),complete=total>0&&filled===total;
    return{text:filled+'/'+total+' '+(complete?'已完成':filled?'部分可用':'无可用映射')+(group.status==='DRAFT'?' · 待配置':''),className:'pill '+(complete?'mapping-done':filled?'mapping-partial':'mapping-missing'),complete,usable:filled>0};
}
function trackingSourceState(source){if(!source)return'历史入口';return({CURRENT:'当前',SUSPECT:'疑似失效',INACTIVE:'已失效',UNSEEN:'手动添加 · 当前未检测',DELETED:'手动删除'})[source.state]+(source.state==='DELETED'&&Number(source.in_latest)?' · 上游仍出现，对应节点已过滤':'')}
function trackingSplitTime(group){return group.has_active_children?group.split_at:null}
function trackingSplitPreview(path){return[path+'.1',path+'.2']}
function trackingDraftWarning(count){return count===2?'':count===1?'当前待配置拆分只有1个子组。二分拆分必须完整保留2个子组。请取消拆分后重新创建。':'旧待配置拆分：'+count+'个子组。当前版本新拆分固定为2个。请取消该待配置拆分后重新创建。'}
function trackingUndoChildren(group,groups){return groups.filter(g=>g.parent_id===group.id&&g.status==='ACTIVE')}
function trackingCanUndo(group,groups){const children=trackingUndoChildren(group,groups);return group.status==='ACTIVE'&&children.length>=2&&!group.has_draft_children&&children.every(g=>!g.has_active_children&&!g.has_draft_children)}
async function createTrackingSplit(group){
    const result=await openDialog({title:'拆分入口组',description:'当前组：'+group.path+'\n将创建：\n'+trackingSplitPreview(group.path).join('\n')+'\n创建后不会立即移动Token，填写目标入口并激活后才分配。',label:'创建子组',submit:()=>api('tracking/groups/'+group.id+'/split','POST',{})});
    if(result){await show('入口追踪');notice(result.children.length+'个待配置子组已创建')}
}
async function undoTrackingSplit(group,groups,mode){
    if(!trackingCanUndo(group,groups))throw Error('请先撤销或处理下级拆分');
    const children=trackingUndoChildren(group,groups),total=children.reduce((sum,g)=>sum+Number(g.token_count),0),mapping=trackingMappingState({...group,has_active_children:0});
    const result=await openDialog({title:'撤销入口组'+group.path+'的拆分',description:'当前：\n'+children.map(g=>g.path+'  '+g.token_count+'个Token').join('\n')+'\n撤销后：'+total+'个Token将全部回到直接父组'+group.path+'。其它主组及兄弟分支不受影响。子组将归档，不删除历史。\n父组当前入口映射：'+mapping.text+'。未映射节点将过滤。'+(mode==='enforced'&&!mapping.usable?'\n父组当前没有可用映射，请配置至少1个当前目标入口后再撤销拆分。':''),danger:true,label:'确认撤销',submit:()=>{if(mode==='enforced'&&!mapping.usable)throw Error('父组当前没有可用映射，请配置至少1个当前目标入口后再撤销拆分。');return api('tracking/groups/'+group.id+'/undo-split','POST')}});
    if(result){await show('入口追踪');notice('拆分已撤销，'+result.moved+'个Token已回到直接父组'+group.path)}
}
async function manageTrackingSource(source,catalog,action){
    const path='tracking/sources'+(source?'/'+encodeURIComponent(source.source_host):'');let input;const adding=action==='add',editing=action==='edit',deleting=action==='delete';
    const result=await openDialog({title:adding?'添加原入口':editing?'修改原入口':deleting?'删除原入口':'恢复原入口',description:adding?'可以提前添加备用入口。当前订阅没有匹配到时不会产生任何节点。仅接受域名、IPv4或IPv6。':editing?'当前：'+source.source_host+'。各组已有target保留，旧入口保留删除标记并过滤。':deleting?(Number(source.in_latest)?'该入口当前仍存在于上游订阅。':'当前最新快照未检测到该入口。')+'删除后对应节点将停止下发，其它已映射节点继续正常工作。允许删除正在使用的入口。':'恢复后保留已有target；最新快照未出现时等待真实节点出现，不会凭空生成节点。',danger:deleting,label:adding?'添加':editing?'确认修改':deleting?'确认删除':'确认恢复',build:body=>{if(adding||editing){const pair=field('原入口域名/IP',source?.source_host||'');input=pair[1];input.required=true;const warning=node('p','','tracking-warning');const update=()=>{const found=catalog.find(s=>s.source_host===input.value.trim().toLowerCase()&&Number(s.in_latest));warning.textContent=found?'':'当前最新订阅未检测到此入口，仍可保存。'};input.oninput=update;body.append(pair[0],warning);update()}},submit:()=>api(path+(action==='restore'?'/restore':''),adding||action==='restore'?'POST':editing?'PATCH':'DELETE',adding||editing?{source_host:input.value}:undefined)});
    if(result){await show('入口追踪');notice('原入口操作已保存')}
}
function trackingSourcePanel(t){
    const box=node('div','','box'),bar=node('div','','toolbar'),catalog=t.sources||[];add(bar,node('strong','原入口管理'),btn('+ 添加原入口',()=>manageTrackingSource(null,catalog,'add')));box.append(bar);
    const stats=t.source_stats||{};box.append(node('p',[['当前入口','current'],['新入口','new'],['未映射','unmapped'],['疑似失效','suspect'],['已失效','inactive'],['手动添加未检测','manual_unseen'],['手动删除','deleted']].map(([label,key])=>label+'：'+(stats[key]||0)).join(' · ')));
    box.append(node('p','当前入口按最新完整成功订阅快照统计；未映射/已删除节点会过滤。疑似失效入口连续缺失3次且距最后检测至少10分钟后标记已失效。','muted'));
    box.append(table(['原入口','来源','状态','首次检测','最后检测','连续缺失','最新订阅是否出现','操作'],catalog.map(s=>{const actions=node('span','','actions');if(s.state==='DELETED')add(actions,btn('恢复',()=>manageTrackingSource(s,catalog,'restore')));else add(actions,btn('修改',()=>manageTrackingSource(s,catalog,'edit')),btn('删除',()=>manageTrackingSource(s,catalog,'delete'),'danger'));return[s.source_host,s.origin==='MANUAL'?'手动添加':'自动识别',trackingSourceState(s),fmtTime(s.first_seen_at),fmtTime(s.last_seen_at),s.missing_count,Number(s.in_latest)?'是':'否',actions]})));return box;
}
async function trackingPage(){
    const t=(await api('tracking')).tracking,leaves=t.groups.filter(g=>g.status==='ACTIVE'&&!g.has_active_children),incomplete=t.groups.filter(g=>(g.status==='DRAFT'||leaves.includes(g))&&!trackingMappingState(g).complete),mode=options(['off','preflight','enforced'].map(x=>[x,stateLabels[x]]));mode.value=t.mode;const top=node('div','','box'),bar=node('div','','toolbar');add(bar,node('strong','入口追踪模式'),mode,btn('保存模式',async()=>{if(mode.value==='enforced'){if(leaves.some(g=>!trackingMappingState(g).usable)){await openDialog({title:'无法启用正式模式',description:leaves.map(g=>'入口组 '+g.path+'：'+trackingMappingState(g).text).join('\n')+'\n每个有效叶子组至少需要1个当前可用目标入口；部分映射允许正式下发。',label:'知道了'});return}if(!await ask({title:'启用正式追踪模式',description:'未映射或已删除节点会过滤，其它有效节点正常下发。没有可用节点时返回503；未知格式或解析失败仍Fail-Closed，不回退原始订阅。',danger:true,label:'确认启用'}))return}const result=await api('tracking/mode','PATCH',{mode:mode.value});await show('入口追踪');publishNotice(result)}));top.append(bar,node('p','关闭模式不修改订阅内容，但仍为 Token 分配稳定入口组。预检模式学习原入口并始终返回原始订阅。','muted'));const s=t.stats_24h,stats=node('div','','stats');[['24h请求',s.requests],['完整成功',s.full_successes],['部分成功',s.partial_successes],['跳过节点',s.skipped_nodes],['失败',s.failures],['未知格式',s.unknown_formats],['映射不完整',s.mapping_incomplete],['解析失败',s.parse_failed],['响应过大',s.response_too_large]].forEach(([k,v])=>stats.append(node('span',k+'：'+v)));top.append(stats);content.append(top,trackingSourcePanel(t));
    if(incomplete.length){const warning=node('div','','box tracking-warning');warning.append(node('strong','当前入口映射提示'));incomplete.forEach(g=>{const m=trackingMappingState(g),missing=Number(g.mapping_count)-Number(g.mapping_filled_count);warning.append(node('div',m.usable?'入口组 '+g.path+'：当前映射 '+m.text+'；还有'+missing+'个入口未配置，该入口对应节点将暂不下发，其它已映射入口正常工作。':'入口组'+g.path+'当前没有任何可用映射，该组Token订阅将返回503。',m.usable?'':'danger'))});content.append(warning)}
    content.append(table(['入口组','状态','Token数量','原入口数量','映射状态','创建时间','拆分时间','操作'],t.groups.map(g=>{
        const actions=node('span','','actions'),leaf=g.status==='ACTIVE'&&!g.has_active_children;
        if(g.status==='DRAFT'||g.status==='ACTIVE')add(actions,btn('编辑入口',()=>editTrackingMappings(g,t.sources)));
        if(leaf&&!g.has_draft_children)add(actions,btn('拆分此组',()=>createTrackingSplit(g)));
        if(g.status==='DRAFT'&&g.path.includes('.'))add(actions,btn('删除',async()=>{if(!await ask({title:'删除待配置子组',description:'将删除：'+g.path+'\n该组尚未激活，不会移动任何Token。其入口映射配置也会删除，剩余待配置子组将连续编号。',danger:true,label:'确认删除'}))return;await api('tracking/groups/'+g.id,'DELETE');await show('入口追踪');notice('待配置子组已删除，剩余子组已重新编号')},'danger'));
        if(leaf&&g.has_draft_children){const children=t.groups.filter(x=>x.parent_id===g.id&&x.status==='DRAFT').map(x=>x.path),warning=trackingDraftWarning(children.length);if(warning)actions.append(node('span',warning,'danger wrap'));add(actions,btn('验证映射',async()=>{if(warning)throw Error(warning);await api('tracking/groups/'+g.id+'/validate-split','POST');notice('子组映射验证通过')}),btn('激活拆分',async()=>{if(warning)throw Error(warning);if(!await ask({title:'激活拆分',description:'父组：'+g.path+'\n子组：'+children.join('、')+'\n将分配 '+g.token_count+' 个Token到子组。其他分支不会变化。',danger:true,label:'确认激活'}))return;const x=await api('tracking/groups/'+g.id+'/activate-split','POST');await show('入口追踪');notice('拆分已激活，分配 '+x.moved+' 个Token')}),btn('取消拆分',async()=>{if(!await ask({title:'取消待配置拆分',description:'父组：'+g.path+'\n将删除：'+children.join('、')+'\n不会改变当前Token分配，也不会改变父组映射。',danger:true,label:'确认取消'}))return;await api('tracking/groups/'+g.id+'/split','DELETE');await show('入口追踪');notice('待配置拆分已取消，Token分配保持不变')},'danger'))}
        if(g.status==='ACTIVE'&&g.has_active_children){if(trackingCanUndo(g,t.groups))add(actions,btn('撤销拆分',()=>undoTrackingSplit(g,t.groups,t.mode),'danger'));else actions.append(node('span','请先撤销或处理下级拆分','danger wrap'))}
        add(actions,btn('查看Token',()=>{tokenGroupFilter=String(g.id);show('Token')}));const state=g.status==='ACTIVE'?(g.has_active_children?'已拆分':g.has_draft_children?'待激活':'已启用'):stateLabels[g.status]||'其他状态',mapping=trackingMappingState(g),path=node('span',g.path,'group-path');path.style.paddingLeft=Math.max(0,g.path.split('.').length-1)*16+'px';return[path,state,g.token_count,g.mapping_count,node('span',mapping.text,mapping.className),fmtTime(g.created_at),fmtTime(trackingSplitTime(g)),actions]
    })))
}
async function settings(){
    const[gateway,rates,summary]=await Promise.all([api('settings/gateway'),api('settings'),api('overview')]),g=gateway.settings,s=rates.settings,o=summary.overview,box=node('div','','box');box.append(node('div','部署配置（只读）：入口 '+(o.gateway_domain||'—')+' · 后台端口 '+(o.admin_port||'—')+' · 后台路径 '+base+' · 证书到期 '+fmtTime(o.certificate_expires_at)+' · 可信代理 '+(o.trusted_proxy_ips||'未配置'),'muted'));const bar=node('div','','formrow'),[lu,upstream]=field('上游代理地址',g.upstream_url),[lk,key]=field('Token GET 参数名',g.token_query_key),[lr,rate]=field('每分钟请求',s.rate_per_minute,'number'),[lb,burst]=field('突发请求余量',s.rate_burst,'number'),[ld,days]=field('日志保留天数',s.log_retention_days,'number'),enabled=node('input');upstream.style.width='320px';enabled.type='checkbox';enabled.checked=s.rate_enabled;add(bar,lu,lk,node('span','订阅路径：'+g.subscribe_path_template),node('span','Token 格式：32位小写十六进制'));add(bar,add(node('label','开启限速 '),enabled),lr,lb,ld);box.append(bar,btn('保存网关设置',async()=>publishNotice(await api('settings/gateway','PATCH',{upstream_url:upstream.value,subscribe_path_template:g.subscribe_path_template,token_query_key:key.value,token_format_profile:g.token_format_profile}))),btn('保存限速',async()=>publishNotice(await api('settings/rate','PATCH',{rate_enabled:enabled.checked,rate_per_minute:Number(rate.value),rate_burst:Number(burst.value)}))),btn('保存保留天数',async()=>{await api('settings/retention','PATCH',{log_retention_days:Number(days.value)});notice('日志保留天数已保存')}));content.append(box);
    const passwordBox=node('div','','box'),[lc,current]=field('当前密码','','password'),[ln,replacement]=field('新密码（至少6位）','','password');current.autocomplete='current-password';replacement.autocomplete='new-password';replacement.maxLength=1024;passwordBox.append(node('strong','修改管理员密码'));add(passwordBox,lc,ln,btn('修改密码',async()=>{await api('admin/password','PATCH',{current_password:current.value,new_password:replacement.value});current.value='';replacement.value='';notice('密码已更新，其他登录会话已失效')}));content.append(passwordBox)
}
